/**
 * Machines glyphs: the sidebar entry's icon and one mark per machine kind —
 * the platform's real brand mark in its colour (paths from simple-icons and
 * the Lima wordmark), a monogram for a brand with no mark. Decorative glyphs
 * draw with `currentColor` on a 16px grid so they ride the surrounding text
 * color in both themes.
 */
import type { ReactNode } from 'react'

interface GlyphProps { size?: number | undefined, className?: string | undefined }

function Svg({ size = 16, className, children }: GlyphProps & { children: ReactNode }): ReactNode {
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth={1.2}
      strokeLinecap="round" strokeLinejoin="round" className={className} aria-hidden="true" focusable="false">
      {children}
    </svg>
  )
}

/** Two stacked server units: the sidebar's Machines entry. */
export function MachinesGlyph(props: GlyphProps): ReactNode {
  return (
    <Svg {...props}>
      <rect x="2.1" y="2.6" width="11.8" height="4.6" rx="1.4" />
      <rect x="2.1" y="8.8" width="11.8" height="4.6" rx="1.4" />
      <path d="M4.6 4.9h.01M4.6 11.1h.01" strokeWidth={1.6} />
      <path d="M8.6 4.9h2.8M8.6 11.1h2.8" />
    </Svg>
  )
}

/** This computer (native): a laptop. */
function NativeGlyph(props: GlyphProps): ReactNode {
  return (
    <Svg {...props}>
      <rect x="3" y="3.2" width="10" height="7" rx="1.2" />
      <path d="M1.6 12.8h12.8" />
    </Svg>
  )
}

// ---------- brand marks ----------

interface BrandMark { path: string, hex: string, viewBox?: string }

/** A brand colour as a readable ink: near-black follows the text, a very pale one deepens toward it. */
function brandInk(hex: string): string {
  const [r, g, b] = [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255)
  const l = 0.2126 * r + 0.7152 * g + 0.0722 * b
  return l < 0.25 ? 'currentColor' : l > 0.6 ? `color-mix(in oklab, #${hex} 68%, #14151a)` : `#${hex}`
}

/** A brand mark in its colour, sized by `size`. */
function BrandGlyph({ icon, size = 16, className }: GlyphProps & { icon: BrandMark }): ReactNode {
  return (
    <svg width={size} height={size} viewBox={icon.viewBox ?? '0 0 24 24'} fill={brandInk(icon.hex)} className={className} aria-hidden="true" focusable="false">
      <path d={icon.path} />
    </svg>
  )
}

/** A monogram for a brand with no mark: its letters in its colour. */
function MonogramGlyph({ text, hex, size = 16, className }: GlyphProps & { text: string, hex: string }): ReactNode {
  return <span aria-hidden="true" className={className} style={{ color: brandInk(hex), fontSize: Math.round(size * 0.6), fontWeight: 700, lineHeight: 1, letterSpacing: '-0.02em' }}>{text}</span>
}

