/** The power glyph of Start/Stop. */
export function PowerGlyph(props: GlyphProps): ReactNode {
  return (
    <Svg {...props}>
      <path d="M8 2.2v5.2" />
      <path d="M4.6 4.2a5 5 0 1 0 6.8 0" />
    </Svg>
  )
}

/** A machine kind's mark: the platform's real brand icon; `os` picks the native machine's (`linux` for a Linux host, `pc` when unknown). */
export function MachineGlyph({ platform, os, ...props }: GlyphProps & { platform: string, os?: 'mac' | 'linux' | 'pc' }): ReactNode {
  if (platform === 'docker') return <BrandGlyph icon={DOCKER} {...props} />
  if (platform === 'apple-container') return <BrandGlyph icon={APPLE} {...props} />
  if (platform === 'lima') return <BrandGlyph icon={LIMA} {...props} />
  if (platform === 'microsandbox') return <MonogramGlyph text="msb" hex="7C3AED" {...props} />
  if (platform === 'native') {
    if (os === 'linux') return <BrandGlyph icon={LINUX} {...props} />
    if (os === 'pc') return <NativeGlyph {...props} />
    return <BrandGlyph icon={APPLE} {...props} />
  }
  return <VmGlyph {...props} />
}
